<script setup lang="ts">
import {provideInputContext} from './inputAssistance'
import {computed,onMounted,ref} from 'vue'
import {api,post,type Task} from './api'
type Question={question_id:string;prompt:string;status:string;locale:string;type:string;options:any[]}
const tasks=ref<Task[]>([]),courseId=ref(''),questions=ref<Question[]>([]),stats=ref<any>(null),type=ref<'single_choice'|'true_false'>('single_choice'),prompt=ref(''),page=ref(1),correct=ref('a'),a=ref(''),b=ref(''),feedbackA=ref(''),feedbackB=ref(''),busy=ref(false),error=ref(''),message=ref(''),batchCount=ref(5)
const completed=computed(()=>tasks.value.filter(item=>item.status==='completed'))
async function refresh(){if(!courseId.value)return;questions.value=await api<Question[]>(`/v1/courses/${encodeURIComponent(courseId.value)}/teacher/questions`);stats.value=await api<any>(`/v1/courses/${encodeURIComponent(courseId.value)}/question-stats`)}
async function create(){error.value='';message.value='';busy.value=true;try{const options=type.value==='true_false'?[{id:'a',text:'正确',feedback:feedbackA.value},{id:'b',text:'错误',feedback:feedbackB.value}]:[{id:'a',text:a.value,feedback:feedbackA.value},{id:'b',text:b.value,feedback:feedbackB.value}];if(!prompt.value.trim()||options.some(item=>!item.text.trim()))throw Error('请填写题干和选项反馈');await post(`/v1/courses/${encodeURIComponent(courseId.value)}/questions`,{locale:'zh-CN',type:type.value,prompt:prompt.value,options,correct_option_id:correct.value,anchor:{page_id:page.value}});message.value='题目草稿已创建，请审核后用于课程';prompt.value='';a.value='';b.value='';feedbackA.value='';feedbackB.value='';await refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function generateBatch(){error.value='';message.value='';busy.value=true;try{const result=await post<any>(`/v1/courses/${encodeURIComponent(courseId.value)}/questions/batch`,{count:batchCount.value,locale:'zh-CN'});message.value=`已生成 ${result.created} 道不重复题目草稿`;await refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function review(q:Question,approved:boolean){await post(`/v1/questions/${encodeURIComponent(q.question_id)}/review`,{approved});await refresh()}
function exportBank(){const blob=new Blob([JSON.stringify({courseId:courseId.value,questions:questions.value,stats:stats.value},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='question-bank-export.json';link.click();URL.revokeObjectURL(url)}
onMounted(async()=>{try{tasks.value=await api<Task[]>('/v1/tasks');courseId.value=completed.value[0]?.id||'';await refresh()}catch(e){error.value=(e as Error).message}})
provideInputContext(()=>({courseId:courseId.value||undefined,page:page.value,language:'zh-CN',context:{question:prompt.value,options:[a.value,b.value],correct:correct.value}}))
</script>
<template>
 <div class="question-bank"><div class="heading"><div><p class="eyebrow">QUESTION BANK</p><h1>题库与随堂练习</h1><p>创建题目、批量生成、审核题目并查看作答统计。</p></div><el-tag effect="plain" round>教师工作区</el-tag></div>
 <section class="panel"><el-form-item label="课程项目"><el-select v-model="courseId" filterable @change="refresh"><el-option v-for="item in completed" :key="item.id" :value="item.id" :label="item.name"/></el-select></el-form-item><el-alert v-if="error" :title="error" type="warning" :closable="false"/><el-alert v-if="message" :title="message" type="success" :closable="false"/><el-form label-position="top"><el-form-item label="题型"><el-radio-group v-model="type"><el-radio value="single_choice">单选题</el-radio><el-radio value="true_false">判断题</el-radio></el-radio-group></el-form-item><el-form-item label="关联页面"><el-input-number v-model="page" :min="1" :max="50"/></el-form-item><el-form-item label="题干"><AssistedTextarea v-model="prompt" type="textarea" :rows="3" assist-label="练习题干" assist-purpose="quiz"/></el-form-item><template v-if="type==='single_choice'"><el-form-item label="选项 A"><AssistedInput v-model="a" assist-label="练习选项 A" assist-purpose="quiz"/><AssistedInput v-model="feedbackA" class="feedback" placeholder="选项反馈" assist-label="选项 A 讲解反馈" assist-purpose="quiz"/></el-form-item><el-form-item label="选项 B"><AssistedInput v-model="b" assist-label="练习选项 B" assist-purpose="quiz"/><AssistedInput v-model="feedbackB" class="feedback" placeholder="选项反馈" assist-label="选项 B 讲解反馈" assist-purpose="quiz"/></el-form-item></template><template v-else><el-form-item label="正确时反馈"><AssistedInput v-model="feedbackA" assist-label="选项 A 讲解反馈" assist-purpose="quiz"/></el-form-item><el-form-item label="错误时反馈"><AssistedInput v-model="feedbackB" assist-label="选项 B 讲解反馈" assist-purpose="quiz"/></el-form-item></template><el-form-item label="正确选项"><el-radio-group v-model="correct"><el-radio value="a">A</el-radio><el-radio value="b">B</el-radio></el-radio-group></el-form-item><el-button type="primary" :loading="busy" @click="create">创建题目草稿</el-button></el-form></section>
 <section class="panel batch-panel"><div><h2>批量生成</h2><p class="muted">依据课程页面教学要点生成不重复的判断题草稿，生成后仍需审核。</p></div><el-input-number v-model="batchCount" :min="1" :max="20"/><el-button :loading="busy" @click="generateBatch">生成下一批</el-button></section>
 <section class="panel"><div class="section-top"><h2>题目审核</h2><div><span>{{questions.length}} 题</span><el-button size="small" @click="exportBank">导出题库</el-button></div></div><div v-for="q in questions" :key="q.question_id" class="question-row"><div><strong>{{q.prompt}}</strong><p>{{q.type==='true_false'?'判断题':'单选题'}} · {{q.status==='APPROVED'?'已审核':'草稿'}}</p></div><div><el-button v-if="q.status!=='APPROVED'" link type="primary" @click="review(q,true)">审核通过</el-button><el-button v-if="q.status==='DRAFT'" link type="danger" @click="review(q,false)">退回</el-button></div></div><div v-if="stats" class="stats-summary">已审核 {{stats.approvedQuestions||0}} 题 · 首次作答 {{stats.attempts||0}} 次 · 正确 {{stats.correct||0}} 次 · 错误 {{stats.wrong||0}} 次</div></section></div>
</template>
<style scoped>.question-bank{max-width:1000px;margin:0 auto}.question-bank .panel{padding:22px;margin-bottom:18px}.feedback{margin-top:8px}.batch-panel{display:flex;align-items:center;justify-content:space-between;gap:20px}.question-row{display:flex;justify-content:space-between;gap:16px;padding:14px 0;border-top:1px solid #e5ede8}.question-row p,.stats-summary{color:#6b8073;font-size:13px}.stats-summary{margin-top:16px;padding-top:14px;border-top:1px solid #e5ede8}@media(max-width:650px){.batch-panel{display:block}.batch-panel .el-input-number{margin:10px 8px 0 0}}
</style>
